package br.com.fintrack.service;
import br.com.fintrack.dto.*; import br.com.fintrack.exception.*; import br.com.fintrack.model.*; import br.com.fintrack.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service public class TransacaoService{
 private final TransacaoRepository transacoes; private final CategoriaRepository categorias; private final UsuarioRepository usuarios;
 public TransacaoService(TransacaoRepository t,CategoriaRepository c,UsuarioRepository u){transacoes=t;categorias=c;usuarios=u;}
 @Transactional public TransacaoDTO criar(Long uid,TransacaoDTO d){validarDespesa(uid,d.valor(),d.tipo(),null);Usuario u=usuarios.findById(uid).orElseThrow(()->new ResourceNotFoundException("Usuário não encontrado."));Categoria c=categoria(uid,d.categoriaId());Transacao t=new Transacao(d.data(),d.descricao().trim(),d.valor(),d.tipo(),d.observacao(),d.mensal(),u,c);return dto(transacoes.save(t));}
 @Transactional(readOnly=true) public List<TransacaoDTO> listar(Long uid,LocalDate inicio,LocalDate fim,Long categoriaId){List<Transacao> lista;if(categoriaId!=null){categoria(uid,categoriaId);lista=transacoes.findByUsuarioIdAndCategoriaIdOrderByDataDesc(uid,categoriaId);}else if(inicio!=null||fim!=null){if(inicio==null||fim==null)throw new ValidationException("Informe as datas inicial e final.");if(inicio.isAfter(fim))throw new ValidationException("A data inicial não pode ser posterior à final.");lista=transacoes.findByUsuarioIdAndDataBetweenOrderByDataDesc(uid,inicio,fim);}else lista=transacoes.findAllByUsuarioIdOrderByDataDesc(uid);return lista.stream().map(this::dto).toList();}
 @Transactional(readOnly=true) public TransacaoDTO buscar(Long uid,Long id){return dto(entidade(uid,id));}
 @Transactional public TransacaoDTO atualizar(Long uid,Long id,TransacaoDTO d){Transacao atual=entidade(uid,id);validarDespesa(uid,d.valor(),d.tipo(),atual);Categoria c=categoria(uid,d.categoriaId());atual.atualizar(d.data(),d.descricao().trim(),d.valor(),d.tipo(),d.observacao(),d.mensal(),c);return dto(atual);}
 @Transactional public void remover(Long uid,Long id){transacoes.delete(entidade(uid,id));}
 @Transactional(readOnly=true) public SaldoDTO saldo(Long uid,LocalDate inicio,LocalDate fim){if(inicio==null)inicio=LocalDate.of(2000,1,1);if(fim==null)fim=LocalDate.now();if(inicio.isAfter(fim))throw new ValidationException("Período inválido.");BigDecimal r=transacoes.sumValorPeriodo(uid,TipoTransacao.RECEITA,inicio,fim);BigDecimal d=transacoes.sumValorPeriodo(uid,TipoTransacao.DESPESA,inicio,fim);return new SaldoDTO(r,d,r.subtract(d),inicio,fim);}
 private void validarDespesa(Long uid,BigDecimal valor,TipoTransacao tipo,Transacao anterior){if(tipo!=TipoTransacao.DESPESA)return;BigDecimal disponivel=saldoTotal(uid);if(anterior!=null){BigDecimal contribuicao=anterior.getTipo()==TipoTransacao.RECEITA?anterior.getValor():anterior.getValor().negate();disponivel=disponivel.subtract(contribuicao);}if(valor.compareTo(disponivel)>0)throw new SaldoInsuficienteException("A despesa é maior que o saldo disponível.");}
 private BigDecimal saldoTotal(Long uid){return transacoes.sumValorByUsuarioIdAndTipo(uid,TipoTransacao.RECEITA).subtract(transacoes.sumValorByUsuarioIdAndTipo(uid,TipoTransacao.DESPESA));}
 private Categoria categoria(Long uid,Long id){return categorias.findByIdAndUsuarioId(id,uid).orElseThrow(()->new ResourceNotFoundException("Categoria não encontrada para este usuário."));}
 private Transacao entidade(Long uid,Long id){return transacoes.findByIdAndUsuarioId(id,uid).orElseThrow(()->new ResourceNotFoundException("Transação não encontrada."));}
 private TransacaoDTO dto(Transacao t){return new TransacaoDTO(t.getId(),t.getData(),t.getDescricao(),t.getValor(),t.getTipo(),t.getObservacao(),t.isMensal(),t.getCategoria().getId(),t.getCategoria().getNome());}
}
